def schema(name,desc,url,faq=None):
    import json
    data={"@context":"https://schema.org","@type":["LocalBusiness","CleaningService"],"name":"TampereSiivous","url":DOMAIN,"telephone":PHONE,"email":EMAIL,"description":desc,"areaServed":["Tampere","Pirkkala","Nokia","Ylöjärvi","Kangasala","Lempäälä"],"address":{"@type":"PostalAddress","addressLocality":"Tampere","addressRegion":"Pirkanmaa","addressCountry":"FI"},"priceRange":"€€"}
    out=[data]
    if faq:
        out.append({"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in faq]})
    return ''.join('<script type="application/ld+json">'+json.dumps(d,ensure_ascii=False)+'</script>' for d in out)

def page(title,desc,path,body,faq=None,ogtitle=None):
    canonical=DOMAIN+('/' if path=='' else '/'+path.strip('/')+'/')
    return f'''<!doctype html><html lang="fi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:locale" content="fi_FI"><meta property="og:title" content="{escape(ogtitle or title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/styles.css">{schema(title,desc,canonical,faq)}</head><body>{topbar()}{nav}{body}{footer()}<script src="/assets/site.js" defer></script></body></html>'''

def hero(h1,lead,crumb='Etusivu',eyebrow='Siivouspalvelu Tampere'):
    return f'''<header class="pagehero"><div class="container"><div class="breadcrumbs"><a href="/">Etusivu</a> / {escape(crumb)}</div><span class="eyebrow">{escape(eyebrow)}</span><h1>{h1}</h1><p>{lead}</p><div class="actions"><a class="btn primary" href="/pyyda-tarjous/">Pyydä maksuton tarjous</a><a class="btn ghost" href="tel:{PHONE_LINK}">Soita {PHONE}</a></div></div></header>'''

def faq_html(items): return '<section class="band"><div class="container"><div class="section-head"><h2>Usein kysyttyä</h2></div><div class="faq">'+''.join(f'<div class="faq-item"><h3>{q}</h3><p>{a}</p></div>' for q,a in items)+'</div></div></section>'

def service_body(h1,lead,crumb,intro,features,includes,faq,keywords=''):
    cards=''.join(f'<div class="feature"><h3>{h}</h3><p>{p}</p></div>' for h,p in features)
    checks=''.join(f'<div class="check"><b>✓</b><span>{x}</span></div>' for x in includes)
    return hero(h1,lead,crumb,keywords or 'Yrityssiivous Tampere')+f'''<main><section><div class="container split"><div class="content">{intro}</div><div class="price-card"><span class="eyebrow">Helppo aloittaa</span><h2>Maksuton kartoitus</h2><p>Kerro tilan koko, käyttötarkoitus ja toivottu siivousrytmi. Teemme selkeän ehdotuksen ilman piilokuluja.</p><a class="btn primary" href="/pyyda-tarjous/">Pyydä tarjous</a></div></div></section><section class="band"><div class="container"><div class="section-head"><h2>Miksi TampereSiivous?</h2><p>Yrityssiivous suunnitellaan tilan käytön mukaan, ei valmiin geneerisen listan perusteella.</p></div><div class="grid">{cards}</div></div></section><section><div class="container split"><div><div class="section-head"><h2>Mitä siivoukseen voidaan sisällyttää?</h2></div><div class="checklist">{checks}</div></div><div class="cta"><h2>Säännöllinen siivous ilman säätöä</h2><p>Sovitaan tehtävät, laatutaso ja aikataulu. Me huolehdimme, että työympäristö pysyy siistinä myös kiireisen arjen keskellä.</p><a class="btn primary" href="/ota-yhteytta/">Kysy lisää</a></div></div></section>{faq_html(faq)}</main>'''

