services={
 'toimistosiivous':('Toimistosiivous Tampereella','Säännöllinen toimistosiivous pitää työympäristön siistinä, viihtyisänä ja valmiina työntekijöille sekä asiakkaille. Palvelemme pieniä ja suuria toimistoja Tampereella.','Toimistosiivous','<h2>Toimistosiivous, joka toimii työpäivän ehdoilla</h2><p>Hyvä toimistosiivous ei häiritse työntekoa. Se tapahtuu oikeaan aikaan, oikeilla menetelmillä ja juuri niissä tiloissa, joissa puhtautta eniten tarvitaan. TampereSiivous suunnittelee ylläpitosiivouksen toimiston koon, käyttöasteen ja toivotun laatutason mukaan.</p><p>Palvelu voi olla päivittäinen, muutaman kerran viikossa tai harvempi ylläpitosiivous. Tarvittaessa yhdistämme mukaan ikkunoiden pesun, lattioiden peruspesun ja muut kausittaiset työt.</p>', [('Sama selkeä palvelusuunnitelma','Sovitaan mitä tehdään jokaisella käynnillä ja mitä tehdään harvemmin.'),('Joustavat työajat','Aamu-, päivä- tai iltasiivous yrityksen toiminnan mukaan.'),('Toimistoon sopivat menetelmät','Huomioimme työpisteet, elektroniikan, neuvottelutilat ja paljon käytetyt kosketuspinnat.')], ['Työpisteiden vapaiden pintojen pyyhintä','Neuvottelu- ja yhteistilojen siivous','Keittiön ja taukotilojen puhdistus','WC-tilojen puhdistus ja tarvikkeiden täydennys sovittaessa','Lattioiden imurointi ja kosteapyyhintä','Roskakorien tyhjennys ja jätteiden lajittelun tuki','Ovien, kahvojen ja kosketuspintojen pyyhintä'], [('Kuinka usein toimisto kannattaa siivota?','Yleinen rytmi on 1–5 kertaa viikossa. Sopiva määrä riippuu henkilöstömäärästä, tilan käyttöasteesta, asiakasliikenteestä ja tilatyypeistä.'),('Voiko toimistosiivouksen tehdä iltaisin?','Kyllä. Siivous voidaan ajoittaa ennen työpäivää, sen jälkeen tai muuhun rauhalliseen ajankohtaan.'),('Sisältyvätkö välineet ja aineet palveluun?','Palvelun sisältö sovitaan tarjouksessa. Voimme toteuttaa kokonaisuuden omilla ammattikäyttöön sopivilla välineillä ja aineilla.')], 'Toimistosiivous Tampere'),
 'yrityssiivous':('Yrityssiivous Tampereella','Yrityssiivous Tampereella toimistoille, liiketiloille ja muille työympäristöille. Räätälöity palvelu, selkeä tarjous ja joustava siivousrytmi.','Yrityssiivous','<h2>Yrityssiivous eri kokoisiin tiloihin</h2><p>Yrityssiivous yhdistää ylläpitosiivouksen, tarvittavat lisätyöt ja ennakoitavan palvelurytmin. Tavoitteena on, että tilat näyttävät siisteiltä henkilöstölle, vieraille ja asiakkaille ilman että yrityksen täytyy johtaa siivousta itse.</p><p>Palvelu sopii muun muassa toimistoihin, studioihin, vastaanottotiloihin, myymälöihin, varastoihin ja pieniin tuotanto- tai työtiloihin.</p>', [('Kohdekohtainen toteutus','Siivous perustuu yrityksen tiloihin, käyttöön ja aukioloaikoihin.'),('Yksi kumppani','Ylläpitosiivous ja kausittaiset lisätyöt voidaan yhdistää samaan palveluun.'),('Skaalautuva palvelu','Siivousrytmiä voidaan muuttaa sesonkien ja käyttöasteen mukana.')], ['Toimisto- ja työtilat','Asiakas- ja vastaanottotilat','Sosiaalitilat ja henkilöstökeittiöt','Saniteettitilat','Lattiat ja sisäänkäynnit','Pölynhallinta ja kosketuspinnat','Kausittaiset tehosiivoukset'], [('Mitä yrityssiivous sisältää?','Sisältö määritellään kohteen mukaan. Tavallisesti siihen kuuluu lattioiden, tasojen, wc- ja taukotilojen sekä yhteisten tilojen säännöllinen puhdistus.'),('Miten yrityssiivous hinnoitellaan?','Hintaan vaikuttavat neliöt, tilatyypit, käyttöaste, siivoustiheys ja palvelun sisältö.'),('Voiko palveluun lisätä ikkunanpesun?','Kyllä. Ikkunanpesut ja monet muut erikoistyöt voidaan sopia erillisinä tai kausittaisina lisäpalveluina.')], 'Yrityssiivous Tampere'),
 'sopimussiivous':('Sopimussiivous Tampereella','Sopimussiivous yrityksille Tampereella. Vakioitu siivousrytmi, sovittu laatutaso ja joustava palvelu toimistoihin ja toimitiloihin.','Sopimussiivous','<h2>Säännöllinen sopimussiivous vähentää yllätyksiä</h2><p>Sopimussiivouksessa määritellään etukäteen tehtävät, siivousrytmi, ajankohta ja mahdolliset jaksotyöt. Se sopii yrityksille, jotka haluavat pitää tilat jatkuvasti siisteinä ilman erillisiä tilauksia.</p><p>Palvelusuunnitelmaa voidaan tarkistaa, jos henkilöstömäärä, tilankäyttö tai tarpeet muuttuvat.</p>', [('Ennakoitava','Tiedät mitä tehdään ja milloin.'),('Joustava','Palvelua voidaan kasvattaa tai keventää tilanteen mukaan.'),('Helppo hallita','Yksi sopimus voi kattaa ylläpidon ja sovitut kausityöt.')], ['Päivittäinen tai viikoittainen ylläpitosiivous','Saniteetti- ja taukotilojen hoito','Lattioiden ylläpito','Roskahuolto sovitusti','Kosketuspintojen puhdistus','Kausityöt ja tehosiivoukset','Laatutason tarkistaminen tarpeen mukaan'], [('Mikä on sopimussiivous?','Sopimussiivous on toistuva palvelu, jossa siivous tehdään sovitulla rytmillä ja sovitun työohjeen mukaisesti.'),('Onko sopimus pakko tehdä pitkäksi aikaa?','Sopimuksen kesto ja ehdot sovitaan tarjouksen yhteydessä yrityksen tarpeen mukaan.'),('Voiko siivoustiheyttä muuttaa myöhemmin?','Kyllä. Siivousrytmiä voidaan tarkistaa, jos tilojen käyttö muuttuu.')], 'Sopimussiivous Tampere'),
 'toimitilasiivous':('Toimitilasiivous Tampereella','Toimitilasiivous Tampereella toimistoihin, työtiloihin, varastoihin ja muihin yritystiloihin. Pyydä kohdekohtainen tarjous.','Toimitilasiivous','<h2>Toimitilasiivous tilan käyttötarkoituksen mukaan</h2><p>Kaikkia toimitiloja ei kannata siivota samalla tavalla. Asiakaspalvelutila, toimisto, varasto ja henkilöstön sosiaalitila vaativat erilaisen työjärjestyksen ja siivoustiheyden.</p><p>Rakennamme palvelun alueittain: mitä siivotaan jokaisella käynnillä, mitä viikoittain ja mitkä tehtävät hoidetaan jaksotöinä.</p>', [('Tilakohtainen työohje','Kohteen eri alueet voidaan siivota eri rytmillä.'),('Järkevä resursointi','Siivous kohdistetaan sinne, missä käyttö ja likaantuminen ovat suurimmat.'),('Lisäpalvelut','Ikkunat, lattiat ja muut erikoistyöt voidaan liittää palveluun.')], ['Toimistot ja neuvotteluhuoneet','Vastaanotto- ja aulatilat','Varastot ja kevyet työtilat','Pukuhuoneet ja sosiaalitilat','Keittiö- ja taukotilat','WC-tilat','Sisäänkäynnit ja kulkureitit'], [('Mihin toimitiloihin palvelu sopii?','Palvelu sopii esimerkiksi toimistoihin, varastoihin, studioihin, vastaanottoihin, pieniin työtiloihin ja erilaisiin yritysten yhteistiloihin.'),('Voidaanko eri tiloja siivota eri tiheydellä?','Kyllä. Tämä on usein kustannustehokkain tapa toteuttaa toimitilasiivous.'),('Palveletteko Pirkanmaalla?','Kyllä. Tampereen lisäksi palvelemme sovitusti lähikunnissa.')], 'Toimitilasiivous Tampere'),
 'liiketilasiivous':('Liiketilasiivous Tampereella','Liiketilasiivous Tampereella myymälöihin, showroomeihin ja asiakastiloihin. Siisti ensivaikutelma ja joustava toteutus.','Liiketilasiivous','<h2>Siisti liiketila tukee asiakaskokemusta</h2><p>Liiketilassa puhtaus näkyy heti. Sisäänkäynti, lattiat, sovituskopit, palvelutiskit ja muut asiakaspinnat tarvitsevat säännöllistä huolenpitoa etenkin vilkkaassa käytössä.</p><p>Siivous voidaan ajoittaa ennen avaamista, sulkemisen jälkeen tai soveltuvissa kohteissa myös päivän aikana.</p>', [('Asiakaspinnat kuntoon','Kiinnitämme huomion tiloihin, jotka muodostavat ensivaikutelman.'),('Aukioloihin sopiva rytmi','Siivous voidaan ajoittaa liiketoiminnan ympärille.'),('Sesonkijousto','Tarvetta voidaan kasvattaa kampanjoiden ja ruuhkahuippujen aikana.')], ['Sisäänkäynnit ja lattiat','Palvelu- ja kassatilat','Sovituskopit','Pöly- ja kosketuspinnat','Henkilöstötilat','WC-tilat','Roskien tyhjennys'], [('Milloin liiketilasiivous voidaan tehdä?','Tyypillisesti ennen avaamista tai sulkemisen jälkeen. Sopiva ajankohta määritellään kohteen mukaan.'),('Voiko siivousta lisätä sesonkiaikana?','Kyllä. Palvelurytmiä voidaan muuttaa esimerkiksi joulun, kampanjoiden tai tapahtumien ajaksi.'),('Teettekö myymälöiden ikkunoita?','Kyllä, ikkunoiden pesu voidaan sopia erilliseksi lisäpalveluksi.')], 'Liiketilasiivous Tampere'),
 'porrassiivous':('Porrassiivous Tampereella','Porrassiivous Tampereella taloyhtiöille ja kiinteistöille. Rappukäytävät, sisäänkäynnit ja yhteiset tilat sovitulla rytmillä.','Porrassiivous','<h2>Porraskäytävät ovat kiinteistön käyntikortti</h2><p>Säännöllinen porrassiivous vähentää irtolikaa, pitää sisäänkäynnit siistinä ja parantaa yhteisten tilojen viihtyisyyttä. Työrytmi voidaan painottaa vuodenajan mukaan.</p><p>Palvelu sopii taloyhtiöille, toimistokiinteistöille ja muille rakennuksille, joissa yhteisten kulkutilojen siisteys on tärkeää.</p>', [('Kausien mukaan','Syksy ja talvi voivat vaatia tiheämpää sisäänkäyntien huoltoa.'),('Selkeä kierros','Sovitut kerrokset ja yhteistilat käydään systemaattisesti läpi.'),('Lisätyöt helposti','Ikkunat, saunatilat tai varastojen yhteistilat voidaan sopia erikseen.')], ['Portaat ja tasanteet','Kaiteet ja kosketuspinnat','Sisäänkäynnit ja tuulikaapit','Hissin pinnat sovittaessa','Yhteiset käytävät','Roskien poisto sovitusti','Muut yhteiset tilat'], [('Kuinka usein rappukäytävä kannattaa siivota?','Rytmi riippuu asukasmäärästä, liikenteestä ja vuodenajasta. Monissa kohteissa 1–3 kertaa viikossa on sopiva lähtökohta.'),('Voiko talvella olla useampi siivouskerta?','Kyllä. Palvelua voidaan painottaa loska- ja hiekoituskaudelle.'),('Teettekö myös muita taloyhtiön tiloja?','Kyllä, sovittavia lisäkohteita voivat olla esimerkiksi yhteiset käytävät, sauna- ja kerhotilat sekä varastojen kulkualueet.')], 'Porrassiivous Tampere'),
 'ikkunanpesu':('Ikkunanpesu yrityksille Tampereella','Ikkunanpesu toimistoihin, liiketiloihin ja yrityksille Tampereella. Kausittainen tai kertaluonteinen palvelu muun siivouksen yhteydessä.','Ikkunanpesu','<h2>Puhtaat ikkunat viimeistelevät toimitilan</h2><p>Ikkunat vaikuttavat tilan valoisuuteen ja yleisilmeeseen. Yritysten ikkunanpesu voidaan tehdä kertaluonteisesti tai sovittuna kausityönä osana muuta siivouspalvelua.</p><p>Kohde arvioidaan ikkunoiden määrän, koon, saavutettavuuden ja pesutavan perusteella.</p>', [('Yrityskohteet','Toimistot, liiketilat ja muut soveltuvat toimitilat.'),('Kausipalvelu','Kevät- ja syyspesut voidaan aikatauluttaa etukäteen.'),('Yhdistettävissä','Ikkunanpesu voidaan liittää sopimussiivouksen lisätyöksi.')], ['Lasipintojen pesu sovitussa laajuudessa','Ikkunoiden sisä- ja ulkopinnat kohteen mukaan','Karmien ja puitteiden pyyhintä sovittaessa','Lasiseinät ja sisälasit','Liiketilan näkyvät lasipinnat','Kausittaiset pesut','Kohdekohtainen turvallisuusarvio'], [('Mitä yrityksen ikkunanpesu maksaa?','Hinta riippuu ikkunoiden määrästä, koosta, rakenteesta ja saavutettavuudesta. Pyydä kohdekohtainen tarjous.'),('Voiko ikkunanpesun yhdistää toimistosiivoukseen?','Kyllä. Se voidaan sopia esimerkiksi kevään ja syksyn jaksotyöksi.'),('Pesettekö myös sisäpuolisia lasiseiniä?','Kyllä, sisälasit ja lasiseinät voidaan sisällyttää palveluun.')], 'Ikkunanpesu Tampere'),
 'erikoissiivous':('Erikoissiivous Tampereella yrityksille','Erikoissiivous yrityksille Tampereella: tehostetut siivoukset, lattioiden peruspesut, tekstiilipinnat, yläpölyt ja muut kohdekohtaiset työt.','Erikoissiivous','<h2>Kun ylläpitosiivous ei yksin riitä</h2><p>Erikoissiivous täydentää säännöllistä ylläpitoa. Tarve voi syntyä kausittain, muutoksen yhteydessä tai silloin, kun tietyt pinnat tarvitsevat perusteellisemman käsittelyn.</p><p>Työmenetelmä valitaan pinnan, lian ja kohteen turvallisuusvaatimusten perusteella.</p>', [('Kohdekohtainen arvio','Valitsemme menetelmän materiaalien mukaan.'),('Sovittu rajaus','Työn sisältö ja laajuus määritellään tarjouksessa.'),('Osaksi vuosikelloa','Kausityöt voidaan aikatauluttaa etukäteen.')], ['Lattioiden peruspesut','Tekstiililattioiden ja kalusteiden puhdistus','Yläpölyjen poisto','Tehostetut pintapuhdistukset','Ikkunanpesut','Muuttojen yhteydessä tehtävät yrityssiivoukset','Muut erikseen sovittavat erikoistyöt'], [('Mitä erikoissiivous tarkoittaa?','Se tarkoittaa ylläpitosiivousta perusteellisempia tai erityismenetelmiä vaativia töitä, kuten lattioiden peruspesua tai tekstiilipintojen syväpuhdistusta.'),('Voiko erikoissiivouksen tilata kertaluonteisesti?','Kyllä. Palvelu voidaan tilata yksittäisenä työnä.'),('Voidaanko työt tehdä viikonloppuna?','Mahdollisuus sovitaan kohteen, työn laajuuden ja ajankohdan mukaan.')], 'Erikoissiivous Tampere'),
 'rakennussiivous':('Rakennussiivous Tampereella','Rakennussiivous Tampereella ja Pirkanmaalla. Rakentamisen aikainen siivous, loppusiivous ja työmaatilojen puhtaanapito sovitusti.','Rakennussiivous','<h2>Siisti työmaa tukee sujuvaa tekemistä</h2><p>Rakennussiivouksen tehtävä on hallita rakentamisen aikaista likaa, pölyä ja jätteitä sekä valmistella tiloja seuraaviin työvaiheisiin. Tarjoamme kohdekohtaisesti rakentamisen aikaista siivousta ja loppusiivousta.</p><p>Työ sovitetaan työmaan vaiheeseen, turvallisuusohjeisiin ja aikatauluun.</p>', [('Vaiheiden mukaan','Siivous sovitetaan työmaan etenemiseen.'),('Turvallinen toteutus','Kohteen perehdytys ja työmaakohtaiset vaatimukset huomioidaan.'),('Loppusiivous','Tilat valmistellaan sovitulle puhtaustasolle ennen käyttöönottoa.')], ['Rakentamisen aikainen pöly- ja irtolian poisto','Työalueiden siistiminen','Jätteiden keräys ja sovittu lajittelu','Työmaatilojen siivous','Loppusiivous','Ikkunoiden pesu sovittaessa','Muut työvaihekohtaiset tehtävät'], [('Mitä rakennussiivous sisältää?','Sisältö riippuu työmaan vaiheesta. Se voi sisältää rakentamisen aikaista puhtaanapitoa, työmaatilojen siivousta ja loppusiivousta.'),('Teettekö loppusiivouksia?','Kyllä, loppusiivous voidaan toteuttaa kohteen vaatimustason ja aikataulun mukaan.'),('Palveletteko Tampereen lisäksi Pirkanmaalla?','Kyllä, kohteita voidaan toteuttaa Tampereella ja sovitusti muualla Pirkanmaalla.')], 'Rakennussiivous Tampere'),
 'muuttosiivous':('Muuttosiivous Tampereella yrityksille ja koteihin','Muuttosiivous Tampereella yritysten toimitiloihin ja koteihin. Huolellinen loppusiivous muuton yhteydessä. Pyydä tarjous.','Muuttosiivous','<h2>Muuttosiivous vanhaan tai uuteen tilaan</h2><p>Muutossa siivouksen pitää osua oikeaan hetkeen. Teemme muuttosiivouksia erityisesti yritysten toimitiloihin sekä erikseen sovittaessa koteihin Tampereella.</p><p>Laajuus määritellään tilan koon, kunnon ja luovutusvaatimusten mukaan.</p>', [('Aikataulutettu','Siivous sovitetaan muuttopäivään ja avainten luovutukseen.'),('Laaja loppusiivous','Työ voidaan mitoittaa tyhjän tilan perusteelliseen puhdistukseen.'),('Lisäpalvelut','Ikkunat ja muut erikseen sovitut työt voidaan liittää mukaan.')], ['Lattiat ja listat','Kaappien ulko- ja sisäpinnat sovittaessa','Keittiön pinnat ja kodinkoneiden ulkopinnat','WC- ja pesutilat','Ovet ja kosketuspinnat','Tyhjät työ- tai asuintilat','Ikkunanpesu erikseen sovittaessa'], [('Miten muuttosiivous hinnoitellaan?','Hinta riippuu pinta-alasta, tilan kunnosta, kalusteiden määrästä ja sovitusta laajuudesta.'),('Voiko siivouksen tehdä avainten luovutuspäivänä?','Usein kyllä, jos aikataulusta sovitaan riittävän ajoissa.'),('Teettekö yritysten toimitilojen muuttosiivouksia?','Kyllä. Yritysmuuttojen yhteydessä voimme siivota vanhan tai uuden toimitilan sovitun laajuuden mukaan.')], 'Muuttosiivous Tampere')
}
