articles=[
('kuinka-usein-toimisto-kannattaa-siivota','Kuinka usein toimisto kannattaa siivota?','Toimiston sopiva siivoustiheys riippuu käyttöasteesta, henkilöstömäärästä ja tilatyypeistä. Katso käytännöllinen opas Tampereen yrityksille.','Toimiston siivoustiheys ei ole pelkkä neliökysymys. Vilkas wc-tila tai henkilöstökeittiö voi vaatia päivittäistä huoltoa, vaikka työpistealueet pärjäisivät harvemmalla rytmillä. Hyvä lähtökohta on jakaa toimisto vyöhykkeisiin: korkean käyttöasteen tilat, normaalin käyttöasteen tilat ja harvemmin käytetyt tilat. Näin siivousta voidaan kohdistaa tehokkaammin.','toimistosiivous Tampere'),
('yrityssiivouksen-hinta','Mistä yrityssiivouksen hinta muodostuu?','Yrityssiivouksen hintaan vaikuttavat muutkin asiat kuin neliöt. Lue mitkä tekijät ratkaisevat toimisto- ja sopimussiivouksen hinnan.','Yrityssiivouksen hintaa arvioitaessa tarkastellaan pinta-alan lisäksi tilojen käyttötapaa, kalustusta, henkilöstömäärää, saniteettitilojen määrää, siivoustiheyttä, kulkuyhteyksiä ja toivottua laatutasoa. Säännöllisessä siivouksessa hyvin tehty mitoitus auttaa välttämään sekä aliresursointia että turhaa työtä.','yrityssiivous hinta Tampere'),
('toimistosiivouksen-tarkistuslista','Toimistosiivouksen tarkistuslista yritykselle','Mitä hyvään toimistosiivoukseen kuuluu? Käytännöllinen tarkistuslista työpisteisiin, neuvottelutiloihin, keittiöön ja wc-tiloihin.','Toimistosiivouksen työohje kannattaa jakaa käyntikohtaisiin tehtäviin ja harvemmin tehtäviin jaksotöihin. Jokaisella käynnillä huomiota saavat yleensä roskat, lattiat, wc-tilat, keittiö ja näkyvät kosketuspinnat. Harvemmin tehtäviä töitä voivat olla yläpölyt, lasipinnat ja lattioiden perusteellisempi hoito.','toimistosiivous tarkistuslista')]
